/**
 * Lifting title enrichment, 2026-11-20.
 *
 * 587 of 801 lifting listings had no Search Console impressions in 90 days,
 * and URL Inspection found 80% of a sample indexed: Google had them and showed
 * them for nothing. Titles were bare product names ("Weld-On Hook"), while
 * buyers of unbranded lifting gear search grade, size, WLL and standard.
 *
 * Each title gains the listing's own working load limit (or, where none is
 * recorded, its size range) and its standard, read from its spec rows and
 * nothing else: same figures, same units. Descriptive "Pattern / standard"
 * values are skipped, as is a standard the title already names. 70 characters
 * at most; 132 listings with no clean range or standard and 73 that would run
 * long are left alone. Approved by the founder from the before/after workbook.
 */
export type TitleFix = { slug: string; from: string; to: string }

